'use strict';

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var dmeanstdev = require( './../lib' );

// FUNCTIONS //
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float64', buffer, [ length ], [ stride ], offset, 'row-major' );
}

// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dmeanstdev, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( dmeanstdev.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function computes mean and stdev for a ndarray', function test( t ) {
	var x;
	var out;
	var v;

	x = new Float64Array( [ 2.0, 1.0, 2.0, -2.0, -2.0, 2.0, 3.0, 4.0 ] );
	out = new Float64Array( 2 );

	v = dmeanstdev( [ vector( x, 4, 2, 1 ), vector( out, 2, 1, 0 ) ] );
	t.deepEqual( v[ 0 ], 1.25, 'mean ok' );
	t.deepEqual( v[ 1 ], 2.5, 'stdev ok' );
		t.end();
});

tape( 'supports empty input', function test( t ) {
	var x;
	var out;
	var v;

	x = new Float64Array( [] );
	out = new Float64Array( 2 );

	v = dmeanstdev( [ vector( x, 0, 1, 0 ), vector( out, 2, 1, 0 ) ] );
	t.strictEqual( isNaN( v[ 0 ] ), true, 'mean is NaN' );
		t.end();
});
